import { addEventEntriesRecorded, addFlightRecorded } from './recordedWrites.mjs';
import { getQualifyingEntryPlan } from '../../../helpers/entries/getQualifyingEntryPlan.mjs';
import { getParticipantId } from '../../../functions/global/extractors.mjs';
import { SINGLE_ELIMINATION, MAIN, QUALIFYING } from '../../../constants/drawDefinitionConstants.mjs';
import { DIRECT_ACCEPTANCE } from '../../../constants/entryStatusValues.mjs';
import { SUCCESS } from '../../../constants/resultConstants.mjs';

function generateFlight({ qualifyingParticipants = [], qualifyingPositions = 0, autoEntryPositions, tournamentRecord, drawParticipants, drawProfile, event, }) {
    const { drawType = SINGLE_ELIMINATION, drawSize = 0, drawName, drawId } = drawProfile;
    const stage = (drawProfile.stage ?? MAIN);
    const entriesCount = drawSize - qualifyingPositions;
    const drawParticipantIds = drawParticipants.slice(0, entriesCount).map(getParticipantId);
    if (drawParticipantIds.length) {
        const result = addEventEntriesRecorded({
            participantIds: drawParticipantIds,
            autoEntryPositions,
            entryStage: stage,
            tournamentRecord,
            event,
        });
        if (result.error)
            return result;
    }
    const drawEntries = drawParticipantIds.map((participantId) => ({
        entryStatus: DIRECT_ACCEPTANCE,
        entryStage: stage,
        participantId,
    }));
    const qualifyingParticipantIds = qualifyingParticipants.map(getParticipantId);
    let qualifyingIndex = 0;
    for (const { participantsCount, entryStageSequence, roundTarget } of getQualifyingEntryPlan(drawProfile.qualifyingProfiles)) {
        const participantIds = qualifyingParticipantIds.slice(qualifyingIndex, qualifyingIndex + participantsCount);
        qualifyingIndex += participantsCount;
        if (!participantIds.length)
            continue;
        const result = addEventEntriesRecorded({
            entryStage: QUALIFYING,
            entryStageSequence,
            autoEntryPositions,
            tournamentRecord,
            participantIds,
            roundTarget,
            event,
        });
        if (result.error)
            return result;
        participantIds.forEach((participantId) => drawEntries.push({ entryStatus: DIRECT_ACCEPTANCE, entryStage: QUALIFYING, entryStageSequence, participantId }));
    }
    const result = addFlightRecorded({
        drawName: drawName || drawType,
        qualifyingPositions,
        drawEntries,
        drawId: drawId,
        event,
        stage,
    });
    if (result.error) {
        return result;
    }
    return { ...SUCCESS };
}

export { generateFlight };
